#include <iostream>
#include <string>
using namespace std;

class Cat {
private:
    string name;
    int fish;

public:
    Cat(string n, int f) : name(n), fish(f) {}

    int getFish() const {
        return fish;
    }

    void show() const {
        cout << name << " 有 " << fish << " 条" << endl;
    }
};

int main() {
    int a = 0;
    cin >> a;

    Cat c1("{name}", a);
    c1.show();
    cout << "下一次是 " << c1.getFish() + 1 << " 条" << endl;
    return 0;
}
